#include "CoreSampler.h"
#include <cstdio>
#include <vector>
#include <algorithm>
#include <cassert>
static unsigned readu(FILE*f){unsigned x;assert(fread(&x,4,1,f)==1);return x;}struct Event{unsigned frame,on,note,velocity;};
int main(int argc,char**argv){assert(argc==4);std::vector<float>sample(273015);FILE*f=fopen(argv[1],"rb");assert(f&&fread(sample.data(),4,sample.size(),f)==sample.size());fclose(f);f=fopen(argv[2],"rb");assert(f&&readu(f)==0x4a364d32);unsigned count=readu(f);for(unsigned k=0;k<count;++k){unsigned frames=readu(f),loop=readu(f);float env[14];assert(fread(env,4,14,f)==14);unsigned ne=readu(f),nb=readu(f);std::vector<unsigned>blocks(nb);for(auto&v:blocks)v=readu(f);std::vector<Event>events(ne);for(auto&e:events){e.frame=readu(f);e.on=readu(f);e.note=readu(f);e.velocity=readu(f);}CoreSampler s;s.init(48000);SampleDataDescriptor d{};d.sampleDescriptor={60,261.6255653005986f,58,63,0,127,bool(loop),175902,272998,0,273014};d.sampleRate=44100;d.channelCount=1;d.sampleCount=273015;d.data=sample.data();s.loadSampleData(d);s.buildKeyMap();s.setADSRAttackDurationSeconds(env[0]);s.setADSRHoldDurationSeconds(env[1]);s.setADSRDecayDurationSeconds(env[2]);s.setADSRSustainFraction(env[3]);s.setADSRReleaseHoldDurationSeconds(env[4]);s.setADSRReleaseDurationSeconds(env[5]);s.setFilterAttackDurationSeconds(env[6]);s.setFilterDecayDurationSeconds(env[7]);s.setFilterSustainFraction(env[8]);s.setFilterReleaseDurationSeconds(env[9]);s.setPitchAttackDurationSeconds(env[10]);s.setPitchDecayDurationSeconds(env[11]);s.setPitchSustainFraction(env[12]);s.setPitchReleaseDurationSeconds(env[13]);char fn[512];snprintf(fn,sizeof fn,"%s/case-%02u-public.f32le.pcm",argv[3],k);FILE*out=fopen(fn,"wb");assert(out);unsigned frame=0,ei=0,bi=0;while(frame<frames){while(ei<events.size()&&events[ei].frame==frame){auto&e=events[ei++];if(e.on)s.playNote(e.note,e.velocity);else s.stopNote(e.note,false);}unsigned n=std::min(blocks[bi++%blocks.size()],frames-frame);if(ei<events.size())n=std::min(n,events[ei].frame-frame);assert(n>0&&n<=16);float l[16]={},r[16]={};float*p[]={l,r};s.render(2,n,p);for(unsigned j=0;j<n;++j){assert(fwrite(l+j,4,1,out)==1&&fwrite(r+j,4,1,out)==1);}frame+=n;}assert(fclose(out)==0);printf("publiccase%u frames%u complete\n",k,frames);fflush(stdout);}fclose(f);}
